/* Bramblehaven application shell. Delegated UI, local saves, original audio, optional PWA. */
(function(){'use strict';
const D=BHData,G=BHGame,A=BHArt,I=A.icon,$=id=>document.getElementById(id),KEY='bramblehaven.save.v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>{if(!Number.isFinite(n))return'0';if(n>=1e6)return(n/1e6).toFixed(1).replace(/\.0$/,'')+'m';if(n>=10000)return(n/1000).toFixed(1).replace(/\.0$/,'')+'k';return Math.floor(n).toLocaleString('en');};
const rate=n=>(n>=0?'+':'')+n.toFixed(Math.abs(n)<10?1:0),secs=n=>n>=60?`${Math.floor(n/60)}m ${Math.ceil(n%60)}s`:`${Math.ceil(n)}s`;
let g=new G(),loadIssue='',hadSave=false,storageOK=true,awayReport=null,installPrompt=null,updateWorker=null;
try{const stored=localStorage.getItem(KEY);if(stored){try{g=G.import(stored);hadSave=true;try{if(JSON.parse(JSON.parse(stored).data).version===1&&!localStorage.getItem(KEY+'.v1-original'))localStorage.setItem(KEY+'.v1-original',stored);}catch{loadIssue='Export your v1 save before starting a fresh campaign; an archive could not be written.';}}catch(e){const backup=localStorage.getItem(KEY+'.backup');if(backup){try{g=G.import(backup);hadSave=true;loadIssue='The most recent save was damaged. Your previous autosave was recovered.';}catch{loadIssue='Your saved town could not be read. It has not been overwritten. You can import a backup in Settings.';}}else loadIssue='Your saved town could not be read. Import a backup in Settings, or begin again.';}}}catch{storageOK=false;loadIssue='Browser storage is unavailable. Export a backup before you close the game.';}
const ui={tab:'town',category:'All',guild:'roster',journal:'charter',blueprint:null,moving:null,selected:null,modal:null,region:0,party:['rowan'],mode:'steady',supply:'standard',target:null,draft:null,tradeAmount:10,intro:true};
const demo=new G();demo.s.expansion=2;demo.s.fame=2700;demo.s.elapsed=38;demo.s.buildings=[{id:1,type:'hall',x:8,y:7,level:3,paused:false}];
const demoBuildings=[['cottage',6,8],['cottage',7,8],['garden',6,7],['garden',10,9],['farm',6,10],['farm',7,10],['windmill',7,11],['bakery',8,10],['market',8,9],['inn',9,7],['tavern',10,7],['smith',10,10],['mine',11,10],['library',10,5],['observatory',11,5],['museum',11,7],['fountain',10,8],['lumber',5,8],['warehouse',5,10],['greenhouse',11,8]];
for(const[type,x,y]of demoBuildings)demo.s.buildings.push({id:demo.s.nextId++,type,x,y,level:type==='inn'?2:1,paused:false});for(const[x,y]of[[5,9],[6,9],[7,9],[9,9],[9,8],[9,10],[9,11],[10,11],[11,11],[9,6],[9,5],[10,6],[11,6],[8,8]])demo.s.buildings.push({id:demo.s.nextId++,type:'path',x,y,level:1,paused:false});demo.s.heroes=D.heroes.slice(0,4).map(h=>({id:h.id,level:3,xp:0,gear:1,rest:0}));
const renderer=new A.Renderer($('world'),()=>ui.intro&&!hadSave?demo:g,(x,y)=>tileClick(x,y));
let previousRank=g.rank,lastFrame=performance.now(),lastUI=0,lastSave=0,accumulator=0,hiddenAt=0,saveWarning=false,dirty=true;
class Sound{
 constructor(){this.ctx=null;this.next=0;this.step=0;}
 ensure(){try{if(!this.ctx)this.ctx=new(window.AudioContext||window.webkitAudioContext)();if(this.ctx.state==='suspended')this.ctx.resume();}catch{}return this.ctx;}
 note(freq,when=0,duration=.18,gain=.035,type='sine'){const c=this.ctx;if(!c||c.state!=='running')return;const o=c.createOscillator(),v=c.createGain(),now=c.currentTime+when;o.type=type;o.frequency.value=freq;v.gain.setValueAtTime(0,now);v.gain.linearRampToValueAtTime(gain,now+.018);v.gain.exponentialRampToValueAtTime(.0001,now+duration);o.connect(v);v.connect(c.destination);o.start(now);o.stop(now+duration+.04);}
 fx(kind){if(!g.s.settings.sfx)return;this.ensure();if(kind==='build'){this.note(196,0,.13,.025,'triangle');this.note(293.66,.06,.16,.024,'triangle');}else if(kind==='discovery'){[392,493.88,587.33,783.99].forEach((f,i)=>this.note(f,i*.09,.6,.035,'sine'));}else if(kind==='reward'){this.note(659.25,0,.16,.025);this.note(880,.07,.25,.023);}else if(kind==='error')this.note(146.83,0,.13,.018,'triangle');else this.note(440,0,.08,.012);}
 music(){if(!g.s.settings.music||document.hidden||ui.intro)return;const c=this.ctx;if(!c||c.state!=='running')return;if(c.currentTime<this.next)return;const chords=[[196,246.94,293.66,369.99],[164.81,196,246.94,293.66],[174.61,220,261.63,329.63],[146.83,196,220,293.66]],pattern=[0,2,1,3,2,1,3,2],chord=chords[Math.floor(this.step/8)%4],note=chord[pattern[this.step%8]];this.note(note*2,0,.65,.013,'sine');if(this.step%8===0)this.note(chord[0]/2,0,2.3,.025,'triangle');this.next=c.currentTime+.39;this.step++;}
}
const sound=new Sound();
function costs(cost,reward=false){return `<span class="cost">${Object.entries(cost||{}).map(([r,n])=>`<span class="token ${reward?'reward':g.s.r[r]+1e-7<n?'short':''}" title="${esc(r==='fame'?'Renown':D.resources[r]?.name||r)}">${I(r==='fame'?'star':r,12)} ${reward?'+':''}${fmt(n)}</span>`).join('')||'<span class="positive">Free</span>'}</span>`;}
function button(label,action,arg='',cls='',disabled=false){return `<button class="btn ${cls}" data-action="${action}"${arg!==''?` data-id="${esc(arg)}"`:''}${disabled?' disabled':''}>${label}</button>`;}
function heading(kicker,title,description=''){return `<div class="panel-heading"><div class="eyebrow">${kicker}</div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>`;}
function progress(value,total,cls=''){return `<div class="progress ${cls}" role="progressbar" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${Math.min(total,Math.floor(value))}"><span style="width:${Math.min(100,value/total*100)}%"></span></div>`;}
function toast(text,kind='info'){const el=document.createElement('div');el.className='toast '+kind;el.innerHTML=I(kind==='discovery'?'star':kind==='error'?'help':'check',17)+`<span>${esc(text)}</span>`;$('toasts').appendChild(el);setTimeout(()=>el.classList.add('fade'),3600);setTimeout(()=>el.remove(),4050);while($('toasts').children.length>3)$('toasts').firstChild.remove();}
function act(result,kind='reward'){if(!result)return;if(result.ok){sound.fx(kind);if(result.message)toast(result.message);dirty=true;save();}else{sound.fx('error');toast(result.message,'error');}return result.ok;}
function save(silent=true){if(!g.s.started||ui.intro)return false;try{const text=g.export(),old=localStorage.getItem(KEY);if(old){try{G.import(old);localStorage.setItem(KEY+'.backup',old);}catch{}}localStorage.setItem(KEY,text);storageOK=true;if(!silent)toast('Town saved on this device.');return true;}catch{storageOK=false;if(!saveWarning){toast('Your town could not be saved. Export a backup from Settings.','error');saveWarning=true;}return false;}}
function catchUp(seconds){if(seconds<20||g.s.settings.speed===0)return null;const elapsed=Math.min(seconds,600),before={...g.s.r},wins=g.s.stats.wins;g.tick(elapsed);const earned={};for(const[r,n]of Object.entries(g.s.r))if(Math.floor(n-before[r])>0)earned[r]=Math.floor(n-before[r]);return{seconds,simulated:elapsed,earned,wins:g.s.stats.wins-wins};}
function migrationSeen(){try{const seen=localStorage.getItem(KEY+'.frontier-seen');localStorage.setItem(KEY+'.frontier-seen','yes');return !!seen;}catch{return false;}}
function start(){sound.ensure();if(!hadSave){awayReport=null;accumulator=0;g.s.name=($('start-name')?.value||'Bramblehaven').trim().slice(0,24)||'Bramblehaven';g.s.started=true;}else awayReport=catchUp(Math.max(0,(Date.now()-g.s.lastSave)/1000));ui.intro=false;$('intro-root').innerHTML='';renderer.people=[];renderer.home();previousRank=g.rank;save();dirty=true;render();if(g.s.migratedFrom===1&&!migrationSeen()){openModal('frontier');}else if(awayReport&&Object.keys(awayReport.earned).length)openModal('away');else if(loadIssue)toast(loadIssue,'error');}
function intro(){const subtitle=hadSave?'The hearth is still warm. Your town is right where you left it.':'The old road ends here. Build somewhere worth coming back to.';
 $('intro-root').innerHTML=`<div class="intro"><div class="intro-content"><div class="intro-mark">${I('seed',23)} AN ORIGINAL GUILD-TOWN TYCOON</div><h1>Bramble<br>haven<span style="color:#c8b479">.</span></h1><div class="intro-sub">GUILD &amp; GROVE</div><div class="intro-line"></div>${loadIssue?`<div class="intro-notice">${esc(loadIssue)}</div>`:''}<p>${subtitle}</p><div class="intro-features"><span>${I('home',15)} Build a town</span><span>${I('compass',15)} Follow the road</span><span>${I('star',15)} Bring back wonders</span></div>${!hadSave?'<label class="input-label" for="start-name">NAME YOUR SETTLEMENT</label><input id="start-name" type="text" value="Bramblehaven" maxlength="24" autocomplete="off" spellcheck="false">':`<p class="tiny muted">${esc(g.s.name)} · Day ${g.day} · ${D.ranks[g.rank-1].name}</p>`}<div>${button((hadSave?'Return to '+esc(g.s.name):'Found your guild')+' '+I('arrow',16),'start','','start')}</div><div class="intro-footer">A town with limits. A road worth earning.<br>v${D.VERSION} · Made for JustPixelll <button data-action="help">How to play</button>${hadSave?'':'<button data-action="import">Import a town</button>'}</div></div></div>`;
}
function renderHUD(){const e=g.economy();$('town-name').textContent=g.s.name;$('brand-mark').innerHTML=I('seed',23);$('settings-icon').innerHTML=I('gear',18);$('center-icon').innerHTML=I('home',16);$('roads-icon').innerHTML=I('map',16);$('roads-icon').classList.toggle('active',renderer.showRoads);$('plan-icon').innerHTML=I('grid',16);$('plan-icon').classList.toggle('active',renderer.planning);$('plan-icon').setAttribute('aria-pressed',String(renderer.planning));$('expand-map').innerHTML=I('plus',15)+'<span class="expand-text">Claim land</span>';
 $('clock').innerHTML=I(g.weather==='Rain'?'rain':g.season==='Winter'?'snow':g.s.elapsed%D.DAY>D.DAY*.78?'moon':'sun',20)+`<span>Day ${g.day}<small>${g.season} · ${g.weather}</small></span>`;$('speed').innerHTML=g.s.settings.speed===0?I('play',13)+'<span>Resume</span>':I('pause',13)+'<span>Pause</span>';$('speed').setAttribute('aria-label',g.s.settings.speed===0?'Resume game':'Pause game');$('speed').classList.toggle('is-paused',g.s.settings.speed===0);
 $('resources').innerHTML=Object.keys(D.resources).map(r=>{const v=g.s.r[r],n=e.rates[r],locked=['ore','tools','knowledge'].includes(r)&&g.rank<3||r==='essence'&&g.rank<6;return `<button class="resource ${locked?'dormant':''}" data-action="resource" data-id="${r}" aria-label="${D.resources[r].name}: ${Math.floor(v)}, ${rate(n)} per game minute" title="${D.resources[r].name}: ${Math.floor(v)} · ${rate(n)}/game minute"><span class="res-icon">${I(r,19)}</span><span class="res-info"><span class="res-name">${D.resources[r].short}</span><strong>${fmt(v)}</strong><span class="rate ${n>=0?'positive':'negative'}">${Math.abs(n)>.05?rate(n):'—'}</span></span></button>`;}).join('');
 const next=D.ranks[g.rank],prev=D.ranks[g.rank-1],pct=next?(g.s.fame-prev.fame)/(next.fame-prev.fame)*100:100;
 $('town-rank').innerHTML=`<div class="rank-top">THE VERDANT FRONTIER · RANK ${g.rank}</div><div class="rank-name">${prev.name}</div><div class="rank-track"><span style="width:${Math.min(100,pct)}%"></span></div><div class="rank-footer"><span>${fmt(g.s.fame)} renown</span><span>${next?'Next: '+fmt(next.fame):'A place in legend'}</span></div>`;
 const chapter=D.chapters[g.s.chapter],ready=chapter&&g.progress(chapter.kind,chapter.target)>=chapter.n;$('quest-peek').innerHTML=chapter?`<button class="quest-chip ${ready?'ready':''}" data-action="quest"><span>${I(ready?'check':'flag',18)}</span><span><small>${ready?'CHARTER READY TO CLAIM':'CHARTER '+(g.s.chapter+1)+' / '+D.chapters.length}</small><strong>${esc(chapter.title)}</strong></span>${I('arrow',14)}</button>`:`<button class="quest-chip ready" data-action="ending">${I('star',18)}<span><small>YOUR FIRST CHAPTER IS COMPLETE</small><strong>The long way home</strong></span></button>`;
 const selectedType=ui.blueprint||g.s.buildings.find(b=>b.id===ui.moving)?.type;renderer.blueprint=ui.blueprint;renderer.moving=ui.moving;renderer.selected=ui.selected;renderer.cursor=ui.draft;
 $('placement').classList.toggle('hidden',!selectedType);$('world').parentElement.classList.toggle('is-building',!!selectedType);
 if(selectedType){const p=ui.draft,issue=p?(ui.moving?g.moveProblem(ui.moving,p.x,p.y):g.placement(selectedType,p.x,p.y)):true;$('placement').innerHTML=`<div><strong>${ui.moving?'Move: ':''}${D.buildings[selectedType].name}</strong><small>${p?'Plot '+(p.x+1)+' / '+(p.y+1)+(issue?' · Unavailable':' · Ready to confirm'):'Tap a plot · Drag to pan · Check preview below'}</small></div>${button(p?'Confirm':'Pick plot','confirmplot','','small',!!issue)}<button class="cancel" data-action="cancelbuild" aria-label="Cancel building">${I('close',15)}</button>`;}

 const readyAch=D.achievements.filter(a=>!g.s.achievements.includes(a.id)&&g.progress(a.kind)>=a.n).length;
 const tabs=[['town','home','Town',g.s.event?1:0],['build','hammer','Build',0],['guild','shield','Guild',0],['explore','compass','Explore',g.s.missions.filter(m=>m.done||m.choice===null&&m.remaining<m.total*.6).length],['journal','book','Journal',readyAch]];
 $('tabs').innerHTML=tabs.map(([id,icon,name,n])=>`<button class="tab ${ui.tab===id?'active':''}" data-action="tab" data-id="${id}" aria-current="${ui.tab===id?'page':'false'}">${I(icon,20)}<span>${name}</span>${n?`<b class="badge">${n}</b>`:''}</button>`).join('');}
function chapterCard(){const c=D.chapters[g.s.chapter];if(!c)return `<div class="celebration">${I('star',27)}<h3>A place worth coming back to.</h3><p>The charter is complete. Your town is yours to keep building—or carry its legacy to a new frontier.</p><div class="gap">${button('The long way home','ending','','primary full')}</div></div>`;const n=g.progress(c.kind,c.target),ready=n>=c.n;return `<div class="card charter"><div class="eyebrow">THE TOWN CHARTER · ${g.s.chapter+1} / ${D.chapters.length}</div><h3>${c.title}</h3><p>${c.text}</p>${progress(n,c.n,'gold')}<div class="progress-label"><span>${ready?'Ready for the next chapter':Math.min(c.n,n)+' / '+c.n+' complete'}</span><span>Chapter reward</span></div>${costs(c.reward,true)}<div class="gap">${button(ready?I('check',15)+' Claim & continue':I('arrow',14)+' Show me the way',ready?'claimchapter':'guide','','full '+(ready?'primary':'secondary'))}</div></div>`;}
function missionsHTML(){return g.s.missions.map(m=>{const r=D.regions[m.region];return `<div class="card mission ${m.done?'done':''}"><div class="mission-head"><h3>${I(r.icon,14)} ${r.name}</h3><span class="pill ${m.done?'green':''}">${m.done?'Returned':secs(m.remaining)}</span></div><p>${m.forage?'Local gathering · no campaign progress':r.stages[Math.min(m.stage,3)]}</p>${progress(m.total-m.remaining,m.total)}<div class="crew">${m.heroes.map(id=>`<img src="${A.portrait(id)}" alt="${D.heroes.find(h=>h.id===id).name}">`).join('')}<small>${m.done?'Rewards are already in your stores.':m.mode==='careful'?'Taking the careful road.':m.mode==='bold'?'Taking the bold road.':'Keeping a steady pace.'}</small></div>${m.done?`<div class="gap">${button(m.result.newRelic?'A new discovery '+I('star',13):'Read the expedition report', 'report',m.id,'full '+(m.result.newRelic?'primary':'secondary'))}</div>`:m.choice===null&&m.remaining<=m.total*.6?`<div class="mission-choice"><span>${I('compass',13)} A fork in the road</span>${button('Decide','missionchoice',m.id,'small primary')}</div>`:''}</div>`;}).join('');}
function townHTML(){const e=g.economy(),warnings=[];if(e.foodLow)warnings.push('Provisions are running low. Add a smallholding, pause food-hungry workshops, or buy food from the merchant.');if(e.labor<.99)warnings.push(`Your workplaces need ${e.demand.toFixed(1)} hands, but ${e.population} residents are available. Assign High priority to essentials, pause unused workplaces, or add homes. Upgrades also need more workers.`);
 const starved=e.rows.filter(row=>row.status.startsWith('Needs ')&&row.status!=='Needs a path');if(starved.length)warnings.push(starved.slice(0,3).map(row=>`${row.d.name}: ${row.status.toLowerCase()}`).join(' · ')+'. Check the ledger for the production chain.');
 return heading('A HOME ON THE OLD ROAD',esc(g.s.name),'A little industry. A little adventure. Room for one more street.')+chapterCard()+`<div class="stats-grid"><div class="mini-stat">${I('people',17)}<strong>${e.population}</strong><small>${e.demand.toFixed(e.demand%1?1:0)} hands needed</small></div><div class="mini-stat">${I('heart',17)}<strong>${Math.round(e.mood)}%</strong><small>${e.foodLow?'Need provisions':e.mood>=90?'Flourishing':'Town spirit'}</small></div><div class="mini-stat">${I('hammer',17)}<strong>${Math.round(e.labor*100)}%</strong><small>Staffing efficiency</small></div></div>${warnings.map(w=>`<div class="tip warning">${I('help',13)} ${w}</div>`).join('')}${!storageOK?'<div class="tip warning"><strong>Save storage is unavailable.</strong>Export a backup from Settings before leaving.</div>':''}${g.s.event?`<div class="card event-card"><div class="event-top">${I('mail',16)}<small>A VISITOR ON THE OLD ROAD</small></div><h3>${D.events[g.s.event.index].title}</h3><p>${D.events[g.s.event.index].text}</p><div class="gap">${button('Hear them out '+I('arrow',13),'event','','secondary full')}</div></div>`:''}${g.s.missions.length?'<div class="section-heading"><h3>Out on the road</h3><small>'+g.s.missions.filter(m=>!m.done).length+' / '+g.partyLimit+' parties</small></div>'+missionsHTML():''}<div class="section-heading"><h3>The town’s pulse</h3><small>Per minute</small></div><div class="card"><table class="ledger"><thead><tr><th>Material</th><th>In stores</th><th>Net flow</th></tr></thead><tbody>${['gold','wood','stone','food'].map(r=>`<tr><td>${I(r,15)} ${D.resources[r].short}</td><td>${fmt(g.s.r[r])}</td><td class="${e.rates[r]>=0?'positive':'negative'}">${rate(e.rates[r])}</td></tr>`).join('')}</tbody></table><div class="actions">${button(I('book',13)+' Ledger','economy','','secondary small')}${button(I('coins',13)+' Merchant','merchant','','secondary small')}</div><p class="footnote">Current net flow after staffing, shortages and reserves. Tap Ledger to set priorities.</p></div><div class="card"><div class="row between"><div><h3>Room to grow</h3><p>${6+g.s.expansion*2} × ${6+g.s.expansion*2} charter · ${g.s.expansion} / 6 expansions</p></div>${I('map',23)}</div><p class="gap">Claim a new ring of land. Move existing buildings for free to lay out your next neighbourhood.</p><div class="gap">${g.s.expansion<6?costs(g.expansionCost()):'<span class="pill green">The whole frontier is yours.</span>'}</div><div class="gap">${button(I('plus',13)+' Expand the charter','expand','','secondary full',g.s.expansion>=6)}</div></div><div class="section-heading"><h3>Trading contracts</h3><small>New offers every 3 days</small></div>${contractsHTML()}<div class="footnote">Day ${g.day} · ${g.season} · ${g.s.stats.visitors} visitors welcomed<br>Autosaved on this device · v${D.VERSION}</div>`;
}
function contractsHTML(){return g.s.contracts.map(c=>`<div class="card contract ${c.done?'done':''}"><div class="contract-name">${esc(c.name)}</div><div class="row between"><div class="row">${costs({[c.resource]:c.amount})}<span class="trade-arrow">→</span>${costs({gold:c.gold,fame:10},true)}</div>${button(c.done?I('check',14):'Deliver','contract',c.id,'small secondary',c.done||!g.affordable({[c.resource]:c.amount}))}</div></div>`).join('');}
function beginBlueprint(id,moving=null){
 if(!D.buildings[id])return;ui.blueprint=moving?null:id;ui.moving=moving;ui.selected=null;ui.draft=null;
 renderer.cursor=null;renderer.hover=null;renderer.keyboardCursor=null;renderer.zoom=Math.max(renderer.zoom,1.2);dirty=true;
 setTab('build');
}
function plannerHTML(){
 const type=ui.blueprint||g.s.buildings.find(b=>b.id===ui.moving)?.type;if(!type)return '';
 const d=D.buildings[type],p=ui.draft,report=p?g.placementReport(type,p.x,p.y,ui.moving):null,row=report?.row;
 const net=report?Object.entries(report.delta).filter(([,n])=>Math.abs(n)>.05):[];
 return `<div class="card planner-card"><div class="eyebrow">${ui.moving?'RELOCATE WITHOUT COST':'PREVIEW BEFORE YOU BUILD'}</div><div class="row between"><h3>${d.name}</h3>${button(I('close',15),'cancelbuild','','secondary small')}</div>
 <p class="gap">${p?'Plot '+(p.x+1)+' / '+(p.y+1)+' · '+report.terrain:'Tap a diamond on the map. Flat plan view keeps roofs out of the way.'}</p>
 ${p?`<div class="plot-nudge"><span>Adjust plot</span>${[['-1,0','↖'],['0,-1','↗'],['0,1','↙'],['1,0','↘']].map(([id,text])=>button(text,'nudge',id,'secondary small')).join('')}</div>`:''}
 ${report?.issue?`<div class="tip warning">${esc(report.issue)}</div>`:''}
 ${row?`<div class="detail-grid"><div><small>Road access</small><strong class="${row.connected?'positive':'negative'}">${row.connected?'Connected':'No road · no output'}</strong></div><div><small>Assigned / needed</small><strong>${row.staff.toFixed(1)} / ${row.workers.toFixed(1)} hands</strong></div></div>
 ${row.workers&&row.staff<row.workers?'<div class="tip warning">Not enough workers. Extra buildings do not create extra labour. Pause a lower priority workplace or add housing.</div>':''}
 <div class="planner-bonuses"><span>${row.terrainBonus?'✓ +35% terrain yield':'No terrain bonus'}</span><span>${row.combos.length?'✓ '+row.combos.map(c=>c.name).join(' · '):'No active neighbourhood bonus'}</span></div>
 <div class="section-heading"><h3>Change to town net flow</h3><small>/ minute at current stock</small></div>
 ${net.length?net.map(([r,n])=>`<div class="detail-row"><span>${I(r,13)} ${D.resources[r].short}</span><strong class="${n>=0?'positive':'negative'}">${rate(n)}</strong></div>`).join(''):'<p>No immediate production change.</p>'}
 <p class="footnote">Includes displaced workers and input costs. Cyan outlines mark potential partners; only road-connected, staffed neighbours activate bonuses.</p>`:''}
 <div class="gap">${ui.moving?'<span class="positive">Relocation is free. Level and priority stay unchanged.</span>':costs(d.cost)}</div>
 <div class="gap">${button(I('check',15)+(ui.moving?' Confirm move':' Confirm build'),'confirmplot','','primary full',!p||!!report?.issue)}</div>
 <p class="footnote">Nothing is spent until you confirm. Dragging only moves the map.</p></div>`;
}
function buildingDetail(type,id){
 const b=type==='building'?g.s.buildings.find(v=>v.id===id):null,t=b?b.type:id,d=D.buildings[t];if(!d)return '';
 const row=b?g.economy().rows.find(r=>r.b.id===b.id):null,lock=b?g.upgradeProblem(b):g.buildingUnlock(t);
 const throughput=(values,sign)=>Object.entries(values||{}).filter(([,n])=>n>.0001).map(([r,n])=>`<div class="detail-row"><span>${I(r,14)} ${D.resources[r].name}</span><strong class="${sign==='+'?'positive':'negative'}">${sign}${n.toFixed(1)} / min</strong></div>`).join('');
 return `<div class="modal-hero"><img src="${A.thumbnail(t,b?.level||1)}" alt="${d.name}"><div><h3>${d.name}</h3><small>${d.cat}${b?' · Level '+b.level+'<br>Plot '+(b.x+1)+' / '+(b.y+1):''}</small></div></div><p>${d.desc}</p>
 ${row?`<div class="detail-grid"><div><small>Road & operations</small><strong>${row.status}</strong></div><div><small>Workers assigned / needed</small><strong>${row.staff.toFixed(1)} / ${row.workers.toFixed(1)}</strong></div></div>`:''}
 <div class="section-heading"><h3>${row?'Output at current staffing':'Base output'}</h3><small>/ minute</small></div>${throughput(row?Object.fromEntries(Object.entries(row.out).map(([k,n])=>[k,n*row.actual])):d.out,'+')||'<p>No direct material output.</p>'}
 <div class="section-heading"><h3>Operating inputs</h3></div>${throughput(row?Object.fromEntries(Object.entries(row.input).map(([k,n])=>[k,n*row.actual])):d.input,'−')||'<p>No direct workplace inputs.</p>'}
 ${row?`<div class="tip">${row.terrainBonus?'+35% terrain yield. ':''}${row.combos.length?row.combos.map(c=>c.name+' +'+Math.round(c.bonus*100)+'%').join(' · '):'No active neighbourhood bonus.'}<br>Bonuses improve yield; they do not multiply input costs.</div>`:''}
 ${d.housing?`<p class="footnote">${d.housing+(b?b.level-1:0)} residents eat ${((d.housing+(b?b.level-1:0))*1.25).toFixed(1)} provisions/minute. Their consumption is in the town ledger.</p>`:''}
 ${b&&d.workers?`<div class="section-heading"><h3>Worker priority</h3></div><div class="mode-options">${['Low','Normal','High'].map((n,i)=>`<button data-action="priority" data-id="${i}" class="${(b.priority??1)===i?'active':''}">${n}</button>`).join('')}</div><p class="footnote">High priority receives workers first. Ties use construction order. Unconnected and paused buildings receive none.</p>`:''}
 ${b?`${!['hall','path'].includes(t)?`<div class="section-heading"><h3>Next upgrade</h3></div>${b.level<5?costs(g.upgradeCost(b)):''}<p class="footnote">${lock?esc(lock):'+45% base throughput; +55% base worker demand. Level 3+ workplaces also consume repair gear.'}</p><div class="gap">${button('Upgrade to level '+Math.min(5,b.level+1),'upgrade',b.id,'full',!!lock||!g.affordable(g.upgradeCost(b)))}</div>`:''}<div class="actions">${t!=='hall'?button(I('move',14)+' Relocate','move',b.id,'secondary'):''}${!['hall','path','cottage','inn'].includes(t)?button(b.paused?'Resume work':'Pause work','pausebuilding',b.id,'secondary'):''}${t!=='hall'?button('Remove','demolish',b.id,'danger'):''}</div>`:`<div class="gap">${costs(d.cost)}</div>${lock?`<div class="tip warning">${esc(lock)}</div>`:''}<div class="gap">${button('Choose a plot','selectfrominfo',id,'full',!!lock)}</div>`}`;
}
function planDetail(){
 const r=D.regions[ui.region];ui.party=ui.party.filter(id=>g.s.heroes.some(h=>h.id===id));
 const p=g.preview(ui.region,ui.party,ui.mode,ui.supply,ui.target),stage=p.stage,slot=g.s.missions.filter(m=>!m.done).length<g.partyLimit;
 const missing=!g.affordable(p.cost),ready=p.warnings.length===0&&!missing&&slot;
 const targets=stage>=4?r.relics.filter(id=>!g.s.relics[id]):[];
 return `<p>${stage<4?'Next: <strong>'+r.stages[stage]+'</strong>':ui.target?'A targeted survey guarantees the selected relic.':'Return journeys give reduced salvage; first-clear rewards are already earned.'}</p>
 <div class="tip"><strong>${r.hazard}</strong>${p.matched?'✓ Covered by your party’s expertise.':'Bring '+r.skills.map(s=>D.skillNames[s]).join(' or ')+' to avoid +18% difficulty.'}${p.requiredGear?'<br>Minimum equipment: tier '+p.requiredGear+' for every party member.':''}${stage===3?'<br>'+ (p.guard?'✓ Protection reduces guardian difficulty by 10%.':'A hero with Protection reduces guardian difficulty.') : ''}</div>
 <div class="section-heading"><h3>Choose your party</h3><small>${ui.party.length} / 3</small></div><div class="party-grid">${g.s.heroes.map(h=>{const d=D.heroes.find(v=>v.id===h.id),busy=g.busy(h.id)||h.rest>0;return `<button class="party-option ${ui.party.includes(h.id)?'selected':''}" data-action="party" data-id="${h.id}" ${busy?'disabled':''}><img src="${A.portrait(h.id)}" alt=""><span><strong>${d.name}</strong><small>Lv ${h.level} · Tier ${h.gear} · ${Math.round(h.condition)}% condition</small><small>${busy?'Not ready':d.skills.map(s=>D.skillNames[s]).join(' / ')}</small></span><span class="party-check">${I(ui.party.includes(h.id)?'check':'plus',13)}</span></button>`;}).join('')}</div>
 <div class="section-heading"><h3>Approach</h3></div><div class="mode-options">${[['careful','Careful','+13 points success','85% loot · less wear'],['steady','Steady','Standard risk','100% loot'],['bold','Bold','−16 points success','135% loot · more wear']].map(([id,n,a,b])=>`<button data-action="mode" data-id="${id}" class="${ui.mode===id?'active':''}">${n}<small>${a}<br>${b}</small></button>`).join('')}</div>
 <div class="section-heading"><h3>Provisioning</h3><small>Spending changes the odds</small></div><div class="supply-options">${Object.entries(D.supplyPolicies).map(([id,d])=>`<button data-action="supply" data-id="${id}" class="${ui.supply===id?'active':''}"><strong>${d.name}</strong><small>${d.desc}</small></button>`).join('')}</div>
 ${targets.length?`<div class="section-heading"><h3>Museum survey</h3><small>Cleared region only</small></div><div class="filters"><button data-action="target" data-id="" class="${!ui.target?'active':''}">Normal journey</button>${targets.map(id=>`<button data-action="target" data-id="${id}" class="${ui.target===id?'active':''}">${D.relics.find(x=>x.id===id).name}</button>`).join('')}</div>`:''}
 <div class="expedition-preview"><div class="row between"><div class="chance">${ui.party.length?Math.round(p.chance*100):0}% <small>${p.tutorial?'guided first scouting trip':p.survey?'guaranteed survey':'success if launched'}</small></div><span class="pill">${I('time',12)} ${secs(p.time)}</span></div>${progress(ui.party.length?p.chance:0,1)}<p><strong>${p.power} party power / ${p.difficulty} difficulty</strong><br>Talents, condition, expertise, approach and supplies are included. Expected equipment wear: ${p.wear}% (${p.wear+8}% on retreat).</p></div>
 ${p.warnings.map(w=>`<div class="tip warning">${esc(w)}</div>`).join('')}
 <div class="section-heading"><h3>Supplies spent on departure</h3></div>${costs(p.cost)}
 ${missing?'<p class="footnote negative">Red costs are missing. Prepare the town’s production chain or reduce the supply plan.</p>':''}
 ${!slot?'<div class="tip warning">All expedition slots are occupied.</div>':''}
 <p class="footnote">${stage===3?'This guardian opens new land, levels and research.':stage<4?'Successful first clears advance the road. Landmarks 1 and 3 award relics.':'Surveys need a working museum and extra insight. No duplicate-drop grind is required.'} No adventurer dies; retreat still costs supplies and equipment condition.</p>
 <div class="gap">${button(ready?I('compass',15)+' Set out':'Preparation incomplete','launch','','primary full',!ready)}</div>`;
}
function reserveControls(){return `<div class="section-heading"><h3>Food reserve</h3></div><div class="filters">${[0,30,60,120].map(n=>`<button data-action="reserve" data-id="${n}" class="${g.s.foodReserve===n?'active':''}">${n} food</button>`).join('')}</div><p class="footnote">Workshops and shops cannot consume this reserve. Residents can. Expedition departures, trading and construction still spend only what you explicitly authorise.</p>`;}
function economyDetail(){const e=g.economy();return `<p>Current net flow includes staff allocation, material shortages, reserves, storage limits, residents and guild wages. Forecasts change as inventories change.</p><table class="ledger"><thead><tr><th>Stock</th><th>Stored</th><th>Net / min</th></tr></thead><tbody>${Object.keys(D.resources).map(r=>`<tr><td>${I(r,14)} ${D.resources[r].short}</td><td>${fmt(g.s.r[r])}${r==='gold'?'':' / '+g.capacity}</td><td class="${e.rates[r]<0?'negative':'positive'}">${rate(e.rates[r])}</td></tr>`).join('')}</tbody></table><div class="tip">${e.population} residents eat ${e.foodUse.toFixed(1)} food/min. Guild wages: ${e.wages.toFixed(1)} crowns/min. ${e.spare.toFixed(1)} unassigned workers.</div>${reserveControls()}<div class="section-heading"><h3>Workplaces</h3><small>Assigned / needed</small></div>${e.rows.filter(r=>r.workers).map(row=>`<button class="workplace-row" data-action="inspect" data-id="${row.b.id}"><span><strong>${row.d.name} · L${row.b.level}</strong><small>${row.status} · ${['Low','Normal','High'][row.b.priority??1]} priority</small></span><span>${row.staff.toFixed(1)} / ${row.workers.toFixed(1)}</span></button>`).join('')}`;}
function merchantDetail(){return `<p>The merchant carries limited basic supplies, restocked each dawn. Equipment, insight and stardust cannot be bought; build their production chains.</p><div class="filters">${[10,25,50].map(n=>`<button data-action="tradeamount" data-id="${n}" class="${ui.tradeAmount===n?'active':''}">${n} units</button>`).join('')}</div>${Object.keys(D.resources).filter(r=>r!=='gold').map(r=>{const t=g.tradeInfo(r),n=ui.tradeAmount;return `<div class="card"><div class="row between"><h3>${I(r,15)} ${D.resources[r].name}</h3><small>Owned: ${fmt(g.s.r[r])}</small></div><p>${t.buyable?t.stock+' available until dawn.':'Produce locally or earn on expeditions.'}</p><div class="actions">${button('Buy '+n+' · '+t.price*n+' crowns','buy',r,'secondary small',!t.buyable||t.stock<n||g.s.r.gold<t.price*n||g.s.r[r]+n>g.capacity)}${button('Sell '+n+' · '+Math.round(t.price*n*.30)+' crowns','sell',r,'secondary small',g.s.r[r]<n)}</div></div>`;}).join('')}`;}
function helpDetail(){return `<div class="tip"><strong>Frontier edition · one game speed</strong>Pause whenever you need to think. There is no fast-forward.</div><h3>Build with a plan</h3><p>Choose a blueprint, tap a plot, and check the preview. Only Confirm build spends resources. Plan view removes tall roofs so every footprint is visible. Use the four diagonal arrows to nudge the target. Paths must connect back to the hearth. Relocation is free.</p><h3 class="gap">Workers, supplies and efficiency</h3><p>Each home adds residents who eat food. Workplaces share that finite labour pool: high priorities receive staff first. Upgrading increases labour and input demand. Terrain and active neighbourhood bonuses increase output without increasing input costs. Keep a food reserve so markets do not sell dinner.</p><h3 class="gap">Earn the next road</h3><p>Clear each region’s guardian to open the next. Inspect the expedition’s expertise, power, minimum equipment and supply requirements. Equipment condition changes power; repair at home. Well-supplied parties cost more but improve their odds and suffer less wear. Bold requires a power advantage and remains riskier.</p><h3 class="gap">Recovery, not game over</h3><p>A retreat wastes supplies and wears equipment, but no one dies. Safe local gathering costs nothing and cannot advance the campaign. It is a fallback when you are short, not the best way to get rich.</p><h3 class="gap">Collection without a lottery wall</h3><p>The first, third and guardian landmarks guarantee their region’s three relics on first clear. A staffed museum can target any missing relic in a cleared region for extra insight.</p><h3 class="gap">Saves &amp; updates</h3><p>Autosave stays on this device. Export a JSON backup before uninstalling or clearing data. v1 saves migrate without deleting your resources, buildings, heroes, relics or achievements. Start a fresh Frontier campaign from Settings to experience the new balance. Your original v1 snapshot and the last retired town are available in Town archives.</p><p class="gap">Away progress is capped at ten real minutes at normal speed. Paused towns remain paused. Existing expeditions finish; no new ones launch automatically.</p><p class="gap">Keyboard: 1–5 sections, Space pause, Escape close. Arrow keys move the map cursor; Enter selects a plot.</p>`;}
function archivesDetail(){let out='<p>These are device-local snapshots, not cloud backups. Export important towns as JSON too. Restoring asks before replacing the active town.</p>';for(const[k,name]of[['v1-original','Original v1 town'],['retired','Last retired town']]){try{const text=localStorage.getItem(KEY+'.'+k);if(text){const a=G.import(text);out+=`<div class="card"><h3>${name}</h3><p>${esc(a.s.name)} · Day ${a.day} · ${a.s.chapter} charter chapters</p><div class="gap">${button('Restore this town','restorearchive',k,'secondary full')}</div></div>`;}}catch{out+='<p class="negative">An archive could not be read.</p>';}}return out;}

function buildHTML(){
 const entries=Object.entries(D.buildings).filter(([id,d])=>id!=='hall'&&(ui.category==='All'||d.cat===ui.category)).sort((a,b)=>a[1].rank-b[1].rank);
 return heading('THE TOWN PLANNER','A place for everything.','Preview a plot, check its road and workers, then confirm. Plan view shows every footprint clearly.')+plannerHTML()+`<div class="filters">${['All','Paths','Homes','Production','Trade','Culture','Guild','Civic','Wonders'].map(c=>`<button class="${ui.category===c?'active':''}" data-action="category" data-id="${c}">${c}</button>`).join('')}</div>`+entries.map(([id,d])=>{
  const lock=g.buildingUnlock(id),unique=d.unique&&g.count(id),selected=ui.blueprint===id;
  return `<div class="card build-card ${lock?'locked':''} ${selected?'selected':''}"><img class="building-image" src="${A.thumbnail(id)}" alt="${d.name}"><div class="build-body"><h3>${d.name}</h3><div class="build-meta">${d.cat}${d.workers?' · '+d.workers+' workers':''}</div><p>${esc(d.desc.split('. ')[0])}.</p>${Object.keys(d.out||{}).length?`<div class="production-line">${Object.entries(d.out).map(([r,n])=>`<span>${I(r,11)} +${n}</span>`).join('')} / min base</div>`:''}</div><div class="build-footer">${costs(d.cost)}<div class="row">${button(I('help',13),'blueprintinfo',id,'secondary btn-square small')}${button(selected?'Selected':unique?'Built':lock?'Locked':'Preview','blueprint',id,'secondary small',!!lock||!!unique)}</div></div>${lock?`<p class="build-lock">${esc(lock)}</p>`:''}</div>`;
 }).join('')+`<div class="tip"><strong>Efficiency is a choice.</strong>Terrain and neighbourhoods improve output without increasing inputs. Upgrades increase both output and staffing; new buildings share the same finite workforce.</div>`;
}
function guildHTML(){return heading('THE HEARTH & THE ROAD','Good company.','An expedition is only as good as the people you send—and the town they come home to.')+`<div class="subtabs"><button class="${ui.guild==='roster'?'active':''}" data-action="guildtab" data-id="roster">Adventurers · ${g.s.heroes.length} / ${D.heroes.length}</button><button class="${ui.guild==='research'?'active':''}" data-action="guildtab" data-id="research">Research · ${g.s.research.length} / ${D.research.length}</button></div>`+(ui.guild==='research'?researchHTML():heroesHTML());}
function heroesHTML(){
 return `<div class="tip"><strong>Guild level cap ${g.heroLevelCap} · Equipment cap ${g.gearCap}</strong>Guardian victories raise the level cap. Frontier research unlocks equipment tiers. Equipment wears on expeditions; repairs restore its power.</div>`+D.heroes.map(d=>{
  const h=g.s.heroes.find(v=>v.id===d.id),locked=g.requirements(d),busy=h&&g.busy(h.id),trainLock=h?g.trainProblem(h):null,gearLock=h?g.gearProblem(h):null;
  return `<div class="card hero-card ${!h&&locked?'locked':''}"><div class="hero-top"><img class="portrait" src="${A.portrait(d.id)}" alt="${d.name}"><div class="hero-heading"><h3>${d.name}</h3><small>${d.role}${h?' · Level '+h.level:''}</small><div class="hero-status">${h?busy?'On expedition':h.rest>0?'Recovering · '+secs(h.rest):'Ready':locked||'Ready to recruit'}</div></div><div class="hero-power">${h?g.power([h.id],-1):d.power}<small>POWER</small></div></div>
 <div class="talent"><strong>${d.talent} · ${d.skills.map(s=>D.skillNames[s]).join(' / ')}</strong>${d.desc}</div>
 ${h?`${progress(h.xp,g.xpNeeded(h),'purple')}<div class="progress-label"><span>${h.level>=g.heroLevelCap?'Guardian victory needed to level further':Math.floor(h.xp)+' / '+g.xpNeeded(h)+' XP'}</span><span>Tier ${h.gear} / 5</span></div>
 <div class="condition-row"><span>${D.gearNames[h.gear]} · <strong class="${h.condition<50?'negative':''}">${Math.round(h.condition)}% condition</strong></span>${button('Repair','repair',h.id,'secondary small',busy||h.condition>=100||!g.affordable(g.repairCost(h)))}</div>${h.condition<100?`<div class="footnote">Repair cost ${costs(g.repairCost(h))}</div>`:''}
 <div class="hero-actions"><div>${button('Train','train',h.id,'secondary small full',!!trainLock||!g.affordable(g.trainCost(h)))}${h.level<g.heroLevelCap?costs(g.trainCost(h)):''}<p class="footnote">${trainLock?esc(trainLock):'One focused session; 35s recovery.'}</p></div><div>${button('Upgrade equipment','equip',h.id,'secondary small full',!!gearLock||!g.affordable(g.gearCost(h)))}${h.gear<5?costs(g.gearCost(h)):''}<p class="footnote">${gearLock?esc(gearLock):D.gearNames[h.gear+1]+' · restores condition.'}</p></div></div>`:
 `<div class="row between gap">${costs(d.cost)}${button(locked?'Locked':'Recruit','recruit',d.id,'secondary small',!!locked||!g.affordable(d.cost))}</div>`}</div>`;
 }).join('');
}
function researchHTML(){
 return `<div class="tip">Research needs a working reading room. Later projects also need discoveries from guardian victories; surplus crowns alone cannot unlock them.</div>`+D.research.map(r=>{
  const done=g.has(r.id),lock=done?null:g.researchProblem(r.id);
  return `<div class="card research-card ${done?'done':''} ${lock?'locked':''}"><span class="research-icon">${I(done?'check':lock?'lock':'knowledge',19)}</span><h3>${r.name}</h3><p>${r.desc}</p>${done?'<span class="pill green">Researched</span>':`<div class="row between">${costs(r.cost)}${button(lock?'Locked':'Research','research',r.id,'small secondary',!!lock||!g.affordable(r.cost))}</div>${lock?`<p class="footnote">${esc(lock)}</p>`:''}`}</div>`;
 }).join('');
}
function worldMap(){const points=[[12,78],[27,55],[41,72],[54,41],[66,55],[79,26],[91,36]];return `<div class="region-map" aria-label="Expedition regions"><svg viewBox="0 0 350 132" preserveAspectRatio="none" aria-hidden="true"><path d="M0 95Q70 128 125 96T250 105T370 73M-10 90Q70 120 125 87T250 95T370 63M-10 24Q70-14 130 27T270 11T380 48" fill="none" stroke="#c7d2b6" stroke-width="1"/><path d="${points.map(([x,y],i)=>(i?'L':'M')+(x*3.5)+','+(y*1.32)).join(' ')}" stroke="#a5b292" stroke-width="1.5" stroke-dasharray="3 4" fill="none"/><text x="18" y="21">THE ROADS BEYOND</text><text x="245" y="119">the uncharted east</text></svg>${points.map(([x,y],i)=>`<button style="left:${x}%;top:${y}%" data-action="plan" data-id="${i}" title="${D.regions[i].name}" aria-label="Plan expedition to ${D.regions[i].name}" ${g.rank<D.regions[i].rank?'disabled':''}>${I(D.regions[i].icon,12)}</button>`).join('')}</div>`;}
function exploreHTML(){
 const ready=g.s.heroes.find(h=>!g.busy(h.id)&&h.rest<=0);
 return heading('THE FRONTIER CAMPAIGN','Earn the next road.','Prepare your party and supply lines. Each guardian opens the next region, not just another roll for loot.')+worldMap()+
 (g.s.missions.length?`<div class="section-heading"><h3>Guild expeditions</h3><small>${g.s.missions.filter(m=>!m.done).length} / ${g.partyLimit} slots</small></div>`+missionsHTML():'')+
 `<div class="card"><h3>Gather near home</h3><p>A safe fallback when supplies are tight. One hero, 45 seconds, no entry cost or equipment requirement. Brings food, timber, stone and a few crowns; no XP, renown or relics.</p><div class="gap">${button('Send a gathering party','forage',ready?.id||'','secondary full',!ready||g.s.missions.filter(m=>!m.done).length>=g.partyLimit)}</div></div>`+
 D.regions.map((r,i)=>{const n=g.s.regionProgress[i],lock=g.regionProblem(i);return `<div class="card route-card ${lock?'locked':''}" style="--region:${r.color}"><div class="route-top"><span class="route-icon">${I(r.icon,36)}</span><h3>${r.name}</h3><p>${r.sub}</p></div><div class="route-body"><div class="route-dots">${[0,1,2,3].map(s=>`<span class="route-dot ${n>s?'done':''}"></span>`).join('')}<span>${n} / 4 · ${r.relics.filter(id=>g.s.relics[id]).length} / 3 relics</span></div><p>${lock?esc(lock):n>=4?'Cleared: return for salvage or a targeted survey.':r.stages[n]}</p><p class="footnote">${r.hazard} · Bring ${r.skills.map(s=>D.skillNames[s]).join(' or ')}${r.minGear?' · Tier '+r.minGear+' equipment':''}</p><div class="gap">${button(lock?'View requirements':n>=4?'Plan a return journey':'Prepare expedition','plan',i,'secondary full')}</div></div></div>`;}).join('')+
 `<div class="tip"><strong>No relic lottery wall.</strong>First clears of landmarks 1 and 3, and the guardian, award that region’s three relics. A working museum can target a missing relic after a region is cleared.</div>`;
}
function journalHTML(){const titles={charter:'The town charter',relics:'A cabinet of wonders',combos:'Better together',achievements:'Small things, well done',chronicle:'The town remembers'};
 return heading('STORIES WORTH KEEPING',titles[ui.journal])+`<div class="subtabs">${[['charter','Charter'],['relics','Relics'],['combos','Neighbourhoods'],['achievements','Achievements'],['chronicle','Chronicle']].map(([id,n])=>`<button class="${ui.journal===id?'active':''}" data-action="journaltab" data-id="${id}">${n}</button>`).join('')}</div>`+({charter:charterHTML,relics:relicsHTML,combos:combosHTML,achievements:achievementsHTML,chronicle:chronicleHTML}[ui.journal])();}
function charterHTML(){return chapterCard()+D.chapters.map((c,i)=>`<div class="card ${i<g.s.chapter?'muted':''}"><div class="row between"><span class="eyebrow" style="margin:0">CHAPTER ${i+1}</span>${I(i<g.s.chapter?'check':i===g.s.chapter?'flag':'lock',14)}</div><h3 class="gap" style="font-family:Georgia,serif;font-size:18px;font-weight:500">${c.title}</h3><p class="gap">${c.text}</p><div class="gap">${costs(c.reward,true)}</div></div>`).join('');}
function relicsHTML(){return `<div class="tip"><strong>${Object.keys(g.s.relics).length} / ${D.relics.length} discoveries</strong>First clears of landmarks 1, 3 and the guardian award their region’s relics. A staffed museum can target missing finds. Each distinct relic adds income to the museum. Duplicates are recorded in the collection but do not multiply that bonus. Legendary relics come from a region’s guardian.</div>`+D.regions.map(r=>`<div class="collection-heading">${I(r.icon,14)} ${r.name}<small>${r.relics.filter(id=>g.s.relics[id]).length} / 3</small></div><div class="relic-grid">${r.relics.map(id=>{const d=D.relics.find(v=>v.id===id),n=g.s.relics[id]||0;return `<button class="relic ${n?d.rarity==='Legendary'?'legendary':d.rarity==='Rare'?'rare':'':'unknown'}" data-action="relic" data-id="${id}" aria-label="${n?d.name:'Undiscovered '+d.rarity+' relic in '+r.name}">${n>1?`<span class="relic-count">×${n}</span>`:''}<span class="relic-symbol">${I(n?d.icon:'lock',24)}</span><strong>${n?d.name:'Undiscovered'}</strong><small>${d.rarity}</small></button>`;}).join('')}</div>`).join('');}
function combosHTML(){return `<div class="tip"><strong>${g.s.combos.length} / ${D.combos.length} neighbourhoods discovered</strong>Place the two building types in any neighbouring plots, including diagonals. Both buildings must be connected and at least half staffed. The bonus improves output without increasing input costs. Multiple different combinations stack; duplicate neighbours do not.</div>`+D.combos.map(c=>{const found=g.s.combos.includes(c.id);return `<div class="card combo-card ${found?'':'unknown'}"><div class="row between"><h3>${found?c.name:'A promising pair'}</h3><span class="pill ${found?'green':''}">${found?'Discovered':'Try this layout'}</span></div><div class="combo-pair"><img src="${A.thumbnail(c.a)}" alt="${D.buildings[c.a].name}"><span>${I('plus',15)}</span><img src="${A.thumbnail(c.b)}" alt="${D.buildings[c.b].name}"></div><p>${c.text}</p><div class="footnote">+${Math.round(c.bonus*100)}% output yield for both neighbours.</div></div>`;}).join('');}
function achievementsHTML(){const ready=D.achievements.filter(a=>!g.s.achievements.includes(a.id)&&g.progress(a.kind)>=a.n);return `<div class="row between" style="margin-bottom:15px"><span class="muted tiny">${g.s.achievements.length} / ${D.achievements.length} claimed</span>${button('Claim ready ('+ready.length+')','claimall','','small primary',!ready.length)}</div>`+[...D.achievements].sort((a,b)=>{const score=x=>g.s.achievements.includes(x.id)?2:g.progress(x.kind)>=x.n?0:1;return score(a)-score(b);}).map(a=>{const claimed=g.s.achievements.includes(a.id),n=g.progress(a.kind),ready=n>=a.n;return `<div class="card achievement ${claimed?'claimed':ready?'ready':''}">${I(claimed?'check':'star',21)}<div class="achievement-body"><h3>${a.name}</h3><p>${a.desc}</p>${claimed?'<div class="footnote">Reward claimed</div>':`${progress(n,a.n,'gold')}<div class="progress-label"><span>${fmt(Math.min(a.n,n))} / ${fmt(a.n)}</span></div><div class="row between">${costs(a.reward,true)}${ready?button('Claim','achievement',a.id,'small primary'):''}</div>`}</div></div>`;}).join('');}
function chronicleHTML(){return `<p class="body-small muted" style="margin-bottom:21px">The last forty entries from a town at the edge of the map.</p>`+(g.s.log.length?g.s.log.map(l=>`<div class="timeline-item"><small>DAY ${Math.floor(l.day)}</small><p>${esc(l.text)}</p></div>`).join(''):`<div class="empty">${I('book',30)}<h3>The first page is yours.</h3><p>Discoveries, visitors, and milestones will be recorded here.</p></div>`);}
function render(){renderHUD();const panel=$('panel'),scroll=panel.scrollTop;panel.innerHTML=({town:townHTML,build:buildHTML,guild:guildHTML,explore:exploreHTML,journal:journalHTML}[ui.tab])();panel.scrollTop=scroll;dirty=false;}
function setTab(tab){if(!['town','build','guild','explore','journal'].includes(tab))return;ui.tab=tab;dirty=true;$('panel').scrollTop=0;render();}
function tileClick(x,y){if(ui.intro)return;sound.ensure();if(ui.blueprint||ui.moving){ui.draft={x,y};renderer.cursor=ui.draft;ui.tab='build';dirty=true;$('panel').scrollTop=0;render();return;}const b=g.at(x,y);if(b){ui.selected=b.id;openModal('building',b.id);}else if(!g.unlocked(x,y))openModal('expand');else{ui.draft={x,y};toast((x+1)+' / '+(y+1)+' · '+G.terrain(x,y)+'. Choose a blueprint to preview here.');}}
function openModal(type,id=null){ui.modal={type,id};renderModal();$('modal-root').querySelector('.modal-content').scrollTop=0;sound.fx('click');setTimeout(()=>{const target=$('modal-root').querySelector('.close-modal');target?.focus({preventScroll:true});},0);}
function closeModal(){ui.modal=null;$('modal-root').innerHTML='';dirty=true;}
function modalFrame(kicker,title,body){return `<div class="modal-overlay" data-action="overlayclose"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><div class="eyebrow">${kicker}</div><h2 id="modal-title">${title}</h2></div><button class="icon-button close-modal" data-action="close" aria-label="Close dialog">${I('close',17)}</button></header><div class="modal-content">${body}</div></section></div>`;}
function renderModal(){if(!ui.modal)return;const{type,id}=ui.modal;let title='',kicker='',body='';
 if(type==='building'||type==='blueprintinfo'){const b=type==='building'?g.s.buildings.find(v=>v.id===id):null,d=D.buildings[b?b.type:id];if(!d){closeModal();return;}title=d.name;kicker='THE TOWN PLANNER';body=buildingDetail(type,id);
 }else if(type==='expand'){title='Room, earned on the road.';kicker='LAND PERMITS';const problem=g.expansionProblem();body=`<p>Each land claim opens another ring of plots. Frontier victories unlock the permits; materials pay for construction.</p><div class="detail-grid"><div><small>Current charter</small><strong>${6+g.s.expansion*2} × ${6+g.s.expansion*2}</strong></div><div><small>Land claims</small><strong>${g.s.expansion} / 6</strong></div></div>${problem?`<div class="tip warning">${esc(problem)}</div>`:''}${g.s.expansion<6?costs(g.expansionCost()):''}<div class="gap">${button('Claim the land','confirmexpand','','full',!!problem||!g.affordable(g.expansionCost()))}</div>`;
 }else if(type==='plan'){title=D.regions[ui.region].name;kicker='PREPARE, DO NOT JUST RETRY';body=planDetail();
 }else if(type==='missionchoice'){const m=g.s.missions.find(v=>v.id===id);if(!m||m.done){closeModal();return;}const r=D.regions[m.region],q=r.choice;title=q.title;kicker='A FORK IN THE ROAD';body=`<div class="report-art">${I(r.icon,52)}</div><p>${q.text}</p><div class="event-choice">${button(q.a+`<span class="outcome">${q.kind==='loot'?'+35 percentage points loot multiplier; −12 points success chance.':'+10 percentage points success chance; −20 points loot multiplier.'}</span>`,'missionoption',0,'full')}${button(q.b+'<span class="outcome">Keep the original odds and rewards.</span>','missionoption',1,'secondary full')}</div><p class="footnote">The party keeps moving. No response means staying on the original route.</p>`;
 }else if(type==='report'){const m=g.s.missions.find(v=>v.id===id);if(!m||!m.result){closeModal();return;}const r=m.result,d=D.relics.find(v=>v.id===r.found),region=D.regions[m.region];title=r.success?'Home, with a story.':'Home, and wiser.';kicker=region.name.toUpperCase();body=`<div class="report-art">${I(d?d.icon:r.success?'flag':'shield',55)}</div><div class="report-text">${d?`<div class="eyebrow">${r.newRelic?'A NEW DISCOVERY':'ANOTHER FIND'} · ${d.rarity.toUpperCase()}</div><h3>${d.name}</h3><p>${d.desc}</p>`:`<h3>${r.success?'A good day on the road.':'The road will wait.'}</h3><p>${r.success?(m.forage?'The gathering party returned with basic supplies. Campaign progress and XP are unchanged.':'Your party returned safely. First-time clears advance the road; return journeys provide salvage.'):'The party withdrew before the final obstacle. Everyone returned with some salvage and experience. Train, equip, or send a stronger party next time.'}</p>`}</div><div class="cost report-loot">${costs(r.reward,true)}</div><p class="footnote" style="text-align:center">These rewards are already in your stores. Full storehouses may have limited material gains. Expedition members received XP; safe local gathering gives supplies only.</p><div class="gap">${button('Close the report '+I('check',14),'ackreport',id,'full')}</div>`;
 }else if(type==='relic'){const d=D.relics.find(v=>v.id===id),r=D.regions.find(v=>v.relics.includes(id)),owned=g.s.relics[id];title=owned?d.name:'An unwritten story.';kicker=d.rarity.toUpperCase()+' RELIC';body=`<div class="report-art">${I(owned?d.icon:'lock',53)}</div><div class="report-text"><p>${owned?d.desc:'Somewhere in '+r.name+', a discovery is waiting. '+(d.rarity==='Legendary'?'Defeat its final guardian to earn this relic.':'Successful journeys through this region may uncover it.')}</p></div><div class="detail-grid"><div><small>Found in</small><strong>${r.name}</strong></div><div><small>Collected</small><strong>${owned||0}</strong></div></div>${owned?'<p class="footnote">Your cabinet of wonders earns +5 base crowns per minute from this distinct discovery. Duplicates do not add to that bonus.</p>':''}`;
 }else if(type==='event'){if(!g.s.event){closeModal();return;}const e=D.events[g.s.event.index];title=e.title;kicker='A VISITOR ON THE OLD ROAD';body=`<p>${e.text}</p><div class="event-choice">${e.choices.map((c,i)=>button(esc(c.text)+`<span class="outcome">${Object.keys(c.cost||{}).length?'Give: '+Object.entries(c.cost).map(([r,n])=>n+' '+D.resources[r].short.toLowerCase()).join(', '):'No cost'}</span><span class="outcome">${Object.keys(c.reward).length?'Receive: '+Object.entries(c.reward).map(([r,n])=>n+' '+(r==='fame'?'renown':D.resources[r].short.toLowerCase())).join(', '):'No reward'}</span>`,'eventoption',i,i===0?'full':'secondary full',!g.affordable(c.cost||{}))).join('')}</div>`;
 }else if(type==='economy'){title='The working town.';kicker='SUPPLY LINES & WORKFORCE';body=economyDetail();
 }else if(type==='resource'){title=D.resources[id].name;kicker='THE TOWN LEDGER';const e=g.economy();body=`<div class="detail-grid"><div><small>In stores</small><strong>${fmt(g.s.r[id])}${id==='gold'?'':' / '+g.capacity}</strong></div><div><small>Current net / minute</small><strong class="${e.rates[id]<0?'negative':'positive'}">${rate(e.rates[id])}</strong></div></div>${id==='food'?reserveControls():''}${e.rows.filter(r=>r.out[id]||r.input[id]).map(r=>`<div class="detail-row"><span>${r.d.name} L${r.b.level}<small> · ${r.status}</small></span><strong>${rate(((r.out[id]||0)-(r.input[id]||0))*r.actual)}</strong></div>`).join('')}<p class="footnote">Includes shortages and storage limits. Resident food and guild wages are accounted for in the net total.</p><div class="gap">${button('Full ledger & priorities','economy','','secondary full')}</div>`;
 }else if(type==='merchant'){title='A little emergency stock.';kicker='THE TRAVELLING MERCHANT';body=merchantDetail();
 }else if(type==='settings'){title='Your town, safely kept.';kicker='BRAMBLEHAVEN · VERSION '+D.VERSION;body=`<p>${window.BrambleNative?'Bundled Android edition. This game runs entirely on your device.':'Offline-ready browser edition. Saves stay in this browser, on this device.'} No account, analytics, advertising, or purchases.</p>${!storageOK?'<div class="tip warning gap"><strong>Local save storage is not available.</strong>Export a file before leaving this session.</div>':''}<label class="input-label" for="rename-town">Settlement name</label><div class="row"><input type="text" id="rename-town" maxlength="24" value="${esc(g.s.name)}">${button('Rename','rename','','small secondary')}</div><div class="settings-row"><span><strong>Music by the hearth</strong><small>An original, softly generated soundtrack.</small></span><button class="toggle ${g.s.settings.music?'on':''}" data-action="music" role="switch" aria-checked="${g.s.settings.music}" aria-label="Music"></button></div><div class="settings-row"><span><strong>Little sounds</strong><small>Building, discoveries, and small victories.</small></span><button class="toggle ${g.s.settings.sfx?'on':''}" data-action="sfx" role="switch" aria-checked="${g.s.settings.sfx}" aria-label="Sound effects"></button></div><div class="section-heading"><h3>Keep a backup</h3><small>${storageOK?'Autosave active':'Export needed'}</small></div><p>Export before uninstalling, clearing browser data, changing devices, or installing an APK with a different signature. A game update should not require deleting your town.</p><div class="actions">${button(I('download',14)+' Export save','export','','secondary')}${button(I('upload',14)+' Import save','import','','secondary')}</div><div class="actions">${button(I('save',13)+' Save now','save','','secondary small')}${button('Copyable backup','copybackup','','secondary small')}</div>${updateWorker?`<div class="tip gap"><strong>A game update is ready.</strong>Your town will be saved before the game reloads.${button('Save & apply update','applyupdate','','full primary gap')}</div>`:''}${!window.BrambleNative?`<div class="actions">${button(I('download',13)+' Install app','install','','secondary small',!installPrompt)}${button('Check for updates','checkupdate','','secondary small')}</div><p class="footnote">Installation is available on supported browsers when served over HTTPS. You can also use your browser’s “Add to Home screen” menu.</p>`:''}<div class="divider"></div><div class="actions">${button(I('help',13)+' Field guide','help','','secondary small')}${button(I('star',13)+' Legacy','ending','','secondary small')}</div><div class="gap">${button('Start a fresh Frontier campaign','reset','','secondary full')}<div class="gap">${button('Town archives','archives','','secondary full')}</div></div><div class="settings-footer">Original code-drawn art and generated music.<br>Inspired by the joy of small management games. No copied game assets.<br>Version ${D.VERSION} · Save format ${D.SAVE_VERSION} · ${window.BrambleNative?'Android, bundled assets':'Web, local storage'}</div>`;
 }else if(type==='help'){title='A town with a plan.';kicker='FRONTIER FIELD GUIDE';body=helpDetail();
 }else if(type==='away'){title='The hearth stayed warm.';kicker='WELCOME HOME';body=`<div class="report-art">${I('home',51)}</div><p>Your town kept working while you were away. Up to ten real minutes count at normal speed; full stores and production shortages still apply.</p><div class="cost report-loot">${costs(awayReport?.earned||{},true)}</div>${awayReport?.wins?`<p class="gap">${awayReport.wins} expedition${awayReport.wins>1?'s':''} returned successfully. Their reports are waiting under Explore.</p>`:''}<p class="footnote">Net positive resource changes are shown above. Provisions and workshop inputs were still consumed. No automatic spending, recruitment, or new expeditions occurred.</p><div class="gap">${button('Good to be back','close','','full')}</div>`;
 }else if(type==='copybackup'){title='A copy of your town.';kicker='PORTABLE SAVE BACKUP';body=`<p>Copy all the text below into a plain-text file ending in .json. Keep it unchanged, including its checksum. You can import that file on another device.</p><textarea id="backup-text" readonly rows="10" aria-label="Complete save backup">${esc(g.export())}</textarea><div class="actions">${button('Select all','selectbackup','','secondary')}${button('Copy to clipboard','clipboard','','secondary')}</div><p class="footnote">This backup contains your town name and game progress. It contains no passwords or account credentials.</p>`;
 }else if(type==='importconfirm'){title='Continue another story?';kicker='IMPORT A TOWN';const incoming=window.BH.pendingImport;body=`<p>This will replace the active town with <strong>${esc(incoming?.s.name)}</strong>, day ${incoming?.day}, rank ${incoming?.rank}. Export your current town first if you need a separate copy.</p><div class="actions">${button('Keep this town','close','','secondary')}${button('Import this save','confirmimport','','primary')}</div>`;
 }else if(type==='frontier'){title='The frontier has changed.';kicker='WELCOME TO VERSION 2';body=`<p>Your old town has been kept, including its resources, buildings, equipment and discoveries. ${originalAvailable()?'An original v1 snapshot is kept in <strong>Settings → Town archives</strong>.':'An original snapshot is not available. Export a backup before closing or replacing this town.'}</p><p class="gap">The new economy has finite labour, food reserves, equipment repairs and guardian-gated progression. An already-rich town cannot show the intended difficulty. Start a fresh Frontier campaign to try the new balance; your old town will remain in the archives.</p><div class="actions">${button('Keep exploring this town','close','','secondary')}${button('Fresh Frontier campaign','reset','','primary')}</div>`;
 }else if(type==='archives'){title='Towns worth keeping.';kicker='LOCAL TOWN ARCHIVES';body=archivesDetail();
 }else if(type==='reset'){title='A different beginning.';kicker='START A NEW TOWN';body=`<p>Start the new Frontier economy from a fresh clearing, with no carried resources or relics. Your current town will be saved in Town archives first. The original v1 snapshot is also kept separately. Export a JSON backup for safekeeping.</p><label class="input-label" for="reset-confirm">Type NEW to confirm</label><input id="reset-confirm" type="text" autocomplete="off" placeholder="NEW"><div class="gap">${button('Start a fresh town','confirmreset','','danger full')}</div>`;
 }else if(type==='demolish'){const b=g.s.buildings.find(v=>v.id===id);if(!b){closeModal();return;}title='Make room for something new?';kicker='REMOVE '+D.buildings[b.type].name.toUpperCase();body=`<p>Remove this building and recover 60% of its original construction cost. Upgrade costs are not refunded. Relocating it is free and keeps its level.</p><div class="actions">${button('Relocate instead','move',id,'secondary')}${button('Remove building','confirmdemolish',id,'danger')}</div>`;
 }else if(type==='ending'){const done=g.s.chapter>=D.chapters.length;title=done?'Leave a light on.':'A road still unfolding.';kicker=done?'THE LONG WAY HOME':'YOUR TOWN’S LEGACY';body=`<div class="report-art">${I(done?'star':'flag',53)}</div><div class="report-text"><h3>${done?'The old road no longer ends here.':'There is more beyond the treeline.'}</h3><p>${done?'It leads to a town with a name. A place of workbenches and windows, books and baking bread. Somewhere people leave—and, more importantly, somewhere they come back to. You built that.':'Complete the town charter to build the Wayhome beacon and uncover the last road in Starlit Reach. Your completed town unlocks a lasting legacy.'}</p></div><div class="detail-grid"><div><small>Charter completed</small><strong>${g.s.chapter} / ${D.chapters.length}</strong></div><div><small>Legacy production bonus</small><strong>+${g.s.legacy*5}%</strong></div></div><p>${done?'Keep building this town for as long as you like. Or begin a fresh frontier with your collected relics and another permanent +5% production bonus (up to +50%). Buildings, heroes, resources, research, achievements, and charter progress start fresh.':'Your discoveries and town can continue growing at your own pace. There is no deadline.'}</p><div class="gap">${button('Keep building this town','close','','full')}</div>${done?`<div class="gap">${button('Begin a new frontier','prestigeconfirm','','secondary full')}</div>`:''}`;
 }else if(type==='prestigeconfirm'){title='Carry the stories onward.';kicker='BEGIN A NEW FRONTIER';body=`<p>Your current buildings, resources, heroes, and research will reset. Your relic collection stays, and your legacy bonus becomes <strong>+${Math.min(50,(g.s.legacy+1)*5)}%</strong>. Export a backup first to keep this town separately.</p><div class="actions">${button('Stay here','close','','secondary')}${button('Found a new settlement','prestige','','primary')}</div>`;
 }
 const old=$('modal-root').querySelector('.modal-content')?.scrollTop||0;$('modal-root').innerHTML=modalFrame(kicker,title,body);$('modal-root').querySelector('.modal-content').scrollTop=old;
}
function retainOriginal(text){try{if(!text||JSON.parse(JSON.parse(text).data).version!==1)return true;if(localStorage.getItem(KEY+'.v1-original'))return true;localStorage.setItem(KEY+'.v1-original',text);return localStorage.getItem(KEY+'.v1-original')===text;}catch{return false;}}
function originalAvailable(){try{return !!localStorage.getItem(KEY+'.v1-original');}catch{return false;}}
function archiveCurrent(){if(!g.s.started)return true;try{const data=g.export();localStorage.setItem(KEY+'.retired',data);if(localStorage.getItem(KEY+'.retired')!==data)throw Error('archive');return true;}catch{toast('The archive could not be saved. Export this town before replacing it.','error');return false;}}
function exportSave(){const data=g.export();save();if(window.BrambleNative?.exportSave){window.BrambleNative.exportSave(data);toast('Choose where to keep your backup.');return;}const blob=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Bramblehaven-'+g.s.name.replace(/[^a-zA-Z0-9_-]/g,'_')+'-day'+g.day+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Save backup exported.');}
function receiveImport(text){try{window.BH.pendingImport=G.import(text);window.BH.pendingImportRaw=text;openModal('importconfirm');}catch(e){toast(e.message||'This save could not be read. Your town was not changed.','error');}}
function requestImport(){if(window.BrambleNative?.importSave){window.BrambleNative.importSave();return;}$('import-file').value='';$('import-file').click();}
$('import-file').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>2000000){toast('That file is too large to be a save.','error');return;}try{receiveImport(await f.text());}catch{toast('The file could not be read.','error');}});
function handle(action,id,element){sound.ensure();let n=Number(id);switch(action){
 case'start':start();break;
 case'planview':renderer.planView=!renderer.planView;dirty=true;toast(renderer.planView?'Plan view: footprints, levels and road access.':'Town view.');break;
 case'confirmplot':{if(!ui.draft||!ui.blueprint&&!ui.moving)break;const{x,y}=ui.draft,result=ui.moving?g.move(ui.moving,x,y):g.build(ui.blueprint,x,y);if(act(result,'build')){const wasMove=!!ui.moving;ui.draft=null;renderer.cursor=null;renderer.hover=null;if(wasMove){ui.moving=null;ui.blueprint=null;}else toast('Built. Choose another plot or close the blueprint.');}break;}
 case'nudge':{if(!ui.draft)break;const[dx,dy]=id.split(',').map(Number);if(!Number.isFinite(dx)||!Number.isFinite(dy))break;ui.draft={x:Math.max(0,Math.min(17,ui.draft.x+dx)),y:Math.max(0,Math.min(17,ui.draft.y+dy))};renderer.cursor=ui.draft;dirty=true;break;}
 case'priority':if(ui.modal?.type==='building'&&act(g.setPriority(ui.modal.id,n),'click'))renderModal();break;
 case'reserve':if(act(g.setReserve(n),'click'))renderModal();break;
 case'supply':if(Object.hasOwn(D.supplyPolicies,id))ui.supply=id;renderModal();break;
 case'target':ui.target=id||null;if(ui.target&&ui.mode==='bold')ui.mode='steady';renderModal();break;
 case'forage':act(g.forage(id),'build');break;
 case'inspect':openModal('building',n);break;
 case'archives':openModal('archives');break;
 case'restorearchive':if(['retired','v1-original'].includes(id)){try{receiveImport(localStorage.getItem(KEY+'.'+id));}catch{toast('That archive cannot be read.','error');}}break;

 case'tab':setTab(id);break;
 case'category':ui.category=id;dirty=true;$('panel').scrollTop=0;break;
 case'guildtab':ui.guild=id;dirty=true;$('panel').scrollTop=0;break;
 case'journaltab':ui.journal=id;dirty=true;$('panel').scrollTop=0;break;
 case'close':closeModal();break;
 case'overlayclose':if(element===eventTargetOverlay)closeModal();break;
 case'speed':g.s.settings.speed=g.s.settings.speed===0?1:0;save();dirty=true;break;
 case'zoomin':renderer.zoomBy(1.2);break;case'zoomout':renderer.zoomBy(1/1.2);break;case'center':renderer.home();break;case'roads':renderer.showRoads=!renderer.showRoads;dirty=true;toast(renderer.showRoads?'Gold paths connect to the hearth. Rust paths are disconnected.':'Road overlay hidden.');break;
 case'blueprint':beginBlueprint(id);sound.fx('click');break;
 case'cancelbuild':ui.blueprint=null;ui.moving=null;ui.selected=null;ui.draft=null;renderer.cursor=null;renderer.hover=null;dirty=true;break;
 case'blueprintinfo':openModal('blueprintinfo',id);break;
 case'selectfrominfo':closeModal();beginBlueprint(id);break;
 case'upgrade':if(act(g.upgrade(n),'build'))renderModal();break;
 case'move':{const b=g.s.buildings.find(b=>b.id===n);closeModal();if(b)beginBlueprint(b.type,n);break;}
 case'pausebuilding':if(act(g.pauseBuilding(n),'click'))renderModal();break;
 case'demolish':openModal('demolish',n);break;
 case'confirmdemolish':if(act(g.demolish(n),'build')){ui.selected=null;closeModal();}break;
 case'expand':openModal('expand');break;
 case'confirmexpand':if(act(g.expand(),'discovery')){closeModal();renderer.zoomBy(.9);}break;
 case'guide':{const c=D.chapters[g.s.chapter];if(c){if(c.tab==='guild'&&c.kind==='research')ui.guild='research';if(c.tab==='build'&&c.target&&typeof c.target==='string')ui.category=D.buildings[c.target]?.cat||'All';setTab(c.tab);if(c.kind==='build'&&typeof c.target==='string')beginBlueprint(c.target);}break;}
 case'quest':if(ui.intro)return;setTab('town');$('panel').scrollTop=0;break;
 case'claimchapter':if(act(g.claimChapter(),'discovery')&&g.s.chapter===D.chapters.length)openModal('ending');break;
 case'achievement':act(g.claimAchievement(id),'reward');break;
 case'claimall':{let total=0;for(const a of D.achievements)if(!g.s.achievements.includes(a.id)&&g.progress(a.kind)>=a.n){g.claimAchievement(a.id);total++;}if(total){sound.fx('reward');toast(total+' achievement rewards claimed.');save();dirty=true;}break;}
 case'recruit':act(g.recruit(id),'discovery');break;
 case'repair':act(g.repair(id),'build');break;
 case'train':act(g.train(id),'reward');break;
 case'equip':act(g.equip(id),'build');break;
 case'research':act(g.research(id),'discovery');break;
 case'plan':ui.region=n;ui.target=null;ui.blueprint=null;ui.moving=null;ui.draft=null;ui.party=ui.party.filter(id=>g.s.heroes.some(h=>h.id===id&&h.rest<=0)&&!g.busy(id));if(!ui.party.length){const h=g.s.heroes.find(h=>h.rest<=0&&!g.busy(h.id));if(h)ui.party=[h.id];}openModal('plan');break;
 case'party':if(ui.party.includes(id))ui.party=ui.party.filter(v=>v!==id);else if(ui.party.length<3)ui.party.push(id);else toast('A party has room for three adventurers.');renderModal();break;
 case'mode':ui.mode=id;renderModal();break;
 case'launch':if(act(g.launch(ui.region,ui.party,ui.mode,ui.supply,ui.target),'build')){closeModal();setTab('explore');}break;
 case'missionchoice':openModal('missionchoice',n);break;
 case'missionoption':if(act(g.chooseMission(ui.modal.id,n),'click'))closeModal();break;
 case'report':openModal('report',n);break;
 case'ackreport':g.acknowledgeMission(n);save();closeModal();break;
 case'relic':openModal('relic',id);break;
 case'event':openModal('event');break;
 case'eventoption':if(act(g.chooseEvent(n),'reward'))closeModal();break;
 case'contract':act(g.fulfill(n),'reward');break;
 case'merchant':openModal('merchant');break;
 case'tradeamount':ui.tradeAmount=n;renderModal();break;
 case'buy':case'sell':if(act(g.trade(id,ui.tradeAmount,action==='buy'),'reward'))renderModal();break;
 case'economy':openModal('economy');break;case'resource':openModal('resource',id);break;
 case'settings':openModal('settings');break;case'help':openModal('help');break;
 case'rename':{const value=($('rename-town')?.value||'').trim().slice(0,24);if(!value){toast('Give the town a name.','error');break;}g.s.name=value;save();toast('The map has been updated.');dirty=true;break;}
 case'music':g.s.settings.music=!g.s.settings.music;save();renderModal();break;
 case'sfx':g.s.settings.sfx=!g.s.settings.sfx;save();renderModal();break;
 case'save':save(false);break;
 case'export':exportSave();break;
 case'import':requestImport();break;
 case'copybackup':openModal('copybackup');break;
 case'selectbackup':$('backup-text')?.select();break;
 case'clipboard':{const text=$('backup-text')?.value;if(!text)break;navigator.clipboard?.writeText(text).then(()=>toast('Backup copied.')).catch(()=>{ $('backup-text').select();toast('Select all, then copy the highlighted text.');});if(!navigator.clipboard){$('backup-text').select();toast('Copy the selected text using your device’s menu.');}break;}
 case'confirmimport':{const incoming=window.BH.pendingImport;if(!incoming)break;if(!archiveCurrent())break;if(!retainOriginal(window.BH.pendingImportRaw)){toast('Original save could not be archived. Export a backup first.','error');break;}g=incoming;awayReport=null;accumulator=0;g.s.started=true;g.s.lastSave=Date.now();hadSave=true;ui.intro=false;$('intro-root').innerHTML='';ui.blueprint=null;ui.moving=null;ui.selected=null;ui.draft=null;renderer.keyboardCursor=null;previousRank=g.rank;renderer.people=[];renderer.home();save();closeModal();setTab('town');toast('Welcome back to '+g.s.name+'.','discovery');window.BH.pendingImport=null;window.BH.pendingImportRaw=null;break;}
 case'reset':openModal('reset');break;
 case'confirmreset':if($('reset-confirm')?.value.trim()!=='NEW'){toast('Type NEW to confirm a fresh town.','error');break;}if(!archiveCurrent())break;g=new G();hadSave=false;ui.intro=true;loadIssue='';ui.blueprint=null;ui.moving=null;ui.selected=null;ui.draft=null;renderer.planView=false;renderer.keyboardCursor=null;closeModal();renderer.people=[];intro();render();break;
 case'ending':openModal('ending');break;case'prestigeconfirm':openModal('prestigeconfirm');break;
 case'prestige':if(!archiveCurrent())break;if(act(g.prestige(g.s.name),'discovery')){ui.blueprint=null;ui.moving=null;ui.selected=null;renderer.people=[];renderer.home();previousRank=g.rank;closeModal();setTab('town');}break;
 case'install':if(installPrompt){installPrompt.prompt();installPrompt.userChoice.then(()=>{installPrompt=null;if(ui.modal?.type==='settings')renderModal();});}else toast('Use your browser’s Add to Home screen option.');break;
 case'checkupdate':if('serviceWorker'in navigator&&!window.BrambleNative){navigator.serviceWorker.getRegistration().then(reg=>{if(reg){reg.update().then(()=>toast('Update check requested. Available updates appear here.')).catch(()=>toast('No connection. Your bundled game still works.','error'));}else toast('Automatic updates require the hosted HTTPS edition.');});}else toast('Install a newer, same-signature APK to update. Keep a backup first.');break;
 case'applyupdate':if(updateWorker){save();updateWorker.postMessage({type:'SKIP_WAITING'});}break;
 }
 if(dirty)render();
}
let eventTargetOverlay=null,uiPointerHeld=false,lastPointerUp=0;
document.addEventListener('pointerdown',()=>{uiPointerHeld=true;},{capture:true});
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,()=>{uiPointerHeld=false;lastPointerUp=performance.now();},{capture:true});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='overlayclose'&&e.target!==el)return;eventTargetOverlay=e.target;handle(el.dataset.action,el.dataset.id??'',el);});
document.addEventListener('keydown',e=>{if(ui.modal&&e.key==='Tab'){const focusable=[...$('modal-root').querySelectorAll('button:not(:disabled),input,textarea,[tabindex="0"]')];if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(e.key==='Escape'){if(ui.modal)closeModal();else handle('cancelbuild','');}if(ui.intro)return;if(!ui.modal&&['1','2','3','4','5'].includes(e.key))setTab(['town','build','guild','explore','journal'][Number(e.key)-1]);if(e.key===' '&&!ui.modal){e.preventDefault();g.s.settings.speed=g.s.settings.speed===0?1:0;save();dirty=true;}});
let nativePaused=false;
function frame(now){const dt=Math.min(.5,Math.max(0,(now-lastFrame)/1000));lastFrame=now;if(!ui.intro&&!document.hidden&&!nativePaused){accumulator+=dt*(g.s.settings.speed===0?0:1);while(accumulator>=.5){g.tick(.5);accumulator-=.5;}
 if(g.rank>previousRank){toast('Town rank '+g.rank+' — '+D.ranks[g.rank-1].name,'discovery');sound.fx('discovery');previousRank=g.rank;dirty=true;}
 while(g.notices.length){const n=g.notices.shift();toast(n.text,n.kind);if(n.kind==='discovery')sound.fx('discovery');dirty=true;}
 if(now-lastSave>10000){save();lastSave=now;}
 if((now-lastUI>1000||dirty)&&!uiPointerHeld&&now-lastPointerUp>180){render();if(ui.modal&&['building','plan','merchant','economy','resource','missionchoice'].includes(ui.modal.type))renderModal();lastUI=now;}
 if(ui.modal?.type==='missionchoice'){const m=g.s.missions.find(m=>m.id===ui.modal.id);if(m?.done){ui.modal={type:'report',id:m.id};renderModal();}}
 sound.music();}
 requestAnimationFrame(frame);
}
function background(){if(!hiddenAt)hiddenAt=Date.now();save();sound.ctx?.suspend();}
function foreground(){lastFrame=performance.now();if(hiddenAt&&!ui.intro){awayReport=catchUp((Date.now()-hiddenAt)/1000);hiddenAt=0;save();if(awayReport&&Object.keys(awayReport.earned).length){toast('Welcome back. Your town kept working.');if(!ui.modal)openModal('away');}}else hiddenAt=0;if(sound.ctx&&g.s.settings.music)sound.ctx.resume();dirty=true;}
document.addEventListener('visibilitychange',()=>{if(document.hidden)background();else if(!nativePaused)foreground();});
window.addEventListener('pagehide',()=>save());window.addEventListener('beforeunload',()=>save());
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.BH={version:D.VERSION,renderer,background:()=>{nativePaused=true;background();},foreground:()=>{nativePaused=false;foreground();},get game(){return g;},get ui(){return ui;},save:()=>save(),pendingImport:null,receiveImportBase64:b=>{try{const bytes=Uint8Array.from(atob(b),c=>c.charCodeAt(0));receiveImport(new TextDecoder().decode(bytes));}catch{toast('The native import could not be read.','error');}},back:()=>{if(ui.modal){closeModal();return true;}if(ui.blueprint||ui.moving){handle('cancelbuild','');return true;}if(ui.tab!=='town'){setTab('town');return true;}save();return false;}};
if('serviceWorker'in navigator&&location.protocol==='https:'&&!window.BrambleNative){navigator.serviceWorker.register('./sw.js').then(reg=>{if(reg.waiting)updateWorker=reg.waiting;reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){updateWorker=worker;toast('A game update is ready in Settings.');if(ui.modal?.type==='settings')renderModal();}});});}).catch(()=>{});let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing)return;refreshing=true;save();location.reload();});}
render();intro();requestAnimationFrame(frame);
})();
